Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1;
const int REAC = -2;
const int BAD_REAC = -3;
const int CAPSULE = ROOM;

int stationMap[MAXN][MAXN], capsuleNum[MAXN][MAXN];
int poison[61][MAXN][MAXN];
int dirX[4] = {-1, 0, 1, 0};
int dirY[4] = {0, -1, 0, 1};

struct Point {
    int x, y, amount;
    Point(int a = 0, int b = 0, int c = 0) : x(a), y(b), amount(c) {}
};

vector<Point> people, capsules;

int residualGraph[MAXN][MAXN];

bool validCell(int x, int y, int n) {
    return x >= 0 && x < n && y >= 0 && y < n && stationMap[x][y] == ROOM;
}

int getType(char c) {
    if (c >= '0' && c <= '9') return ROOM;
    if (c == 'Y') return REAC;
    if (c == 'Z') return BAD_REAC;
    return -1;
}

int getValue(char c) {
    return c - '0';
}

void expandPoison(int x, int y, int T, int n) {
    poison[0][x][y] = 1;
    for (int t = 1; t <= T; ++t) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (poison[t - 1][i][j]) {
                    poison[t][i][j] = 1;
                    for (int d = 0; d < 4; ++d) {
                        int nx = i + dirX[d];
                        int ny = j + dirY[d];
                        if (validCell(nx, ny, n)) poison[t][nx][ny] = 1;
                    }
                }
            }
        }
    }
}

int shortestPath(const Point &from, const Point &to, int n, int limit) {
    vector<bitset<MAXN>> visited(n);
    queue<pair<int, Point>> q;
    q.push({0, from});
    visited[from.x][from.y] = 1;

    while (!q.empty()) {
        auto cur = q.front();
        q.pop();

        int t = cur.first;
        Point p = cur.second;

        if (p.x == to.x && p.y == to.y) return t;
        if (t == limit) continue;
        if (poison[t][p.x][p.y]) continue;

        for (int d = 0; d < 4; ++d) {
            Point nxt(p.x + dirX[d], p.y + dirY[d], 0);
            if (validCell(nxt.x, nxt.y, n) && !visited[nxt.x][nxt.y] && !poison[t][nxt.x][nxt.y]) {
                visited[nxt.x][nxt.y] = 1;
                q.push({t + 1, nxt});
            }
        }
    }

    return 999;
}

long long maxFlow(int s, int t) {
    int parent[MAXN];
    long long total = 0;

    while (true) {
        for (int i = 0; i < MAXN; ++i) parent[i] = -1;

        queue<int> q;
        q.push(s);
        parent[s] = s;
        bool found = false;

        while (!q.empty() && !found) {
            int u = q.front();
            q.pop();

            for (int v = 0; v < MAXN; ++v) {
                if (parent[v] == -1 && residualGraph[u][v] > 0) {
                    parent[v] = u;
                    if (v == t) {
                        found = true;
                        break;
                    }
                    q.push(v);
                }
            }
        }

        if (!found) break;

        int push = INT_MAX;
        for (int v = t; v != s; v = parent[v]) {
            push = min(push, residualGraph[parent[v]][v]);
        }

        for (int v = t; v != s; v = parent[v]) {
            residualGraph[parent[v]][v] -= push;
            residualGraph[v][parent[v]] += push;
        }

        total += push;
    }

    return total;
}

int main() {
    int N, T;
    scanf(" %d %d", &N, &T);

    Point bad(0, 0, 0);
    char ch;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            int type = getType(ch);
            int val = getValue(ch);

            stationMap[i][j] = type;
            if (type == ROOM && val > 0) people.push_back(Point(i, j, val));
            if (type == BAD_REAC) bad = Point(i, j, 0);
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            int type = getType(ch);
            int val = getValue(ch);

            if (type == CAPSULE && val > 0) {
                capsules.push_back(Point(i, j, val));
                capsuleNum[i][j] = val;
            }
        }
    }

    int S = 0, SNK = MAXN - 1;

    for (size_t i = 0; i < people.size(); ++i)
        residualGraph[S][(int)i * 2 + 1] += people[i].amount;

    for (size_t i = 0; i < capsules.size(); ++i)
        residualGraph[(int)i * 2 + 2][SNK] += capsules[i].amount;

    expandPoison(bad.x, bad.y, T, N);

    for (size_t i = 0; i < people.size(); ++i) {
        for (size_t j = 0; j < capsules.size(); ++j) {
            int t = shortestPath(people[i], capsules[j], N, T);
            if (t <= T) residualGraph[(int)i * 2 + 1][(int)j * 2 + 2] += 999;
        }
    }

    printf("%lld\n", maxFlow(S, SNK));
    return 0;
}
